<template>
  <BaseModal :zIndex="zIndex" :onClose="onClose" :maskClosable="true" placement="bottom">
    <div class="dialog-container">
      <div class="history-dialog">
        <!-- 顶部指示器 -->
        <div class="home-indicator-top"></div>
        
        <!-- 搜索框区域 -->
        <div class="search-container">
          <div class="search-input-wrapper">
            <input 
              type="text" 
              :placeholder="t('searchPlaceholder')"
              v-model="searchQuery"
              class="search-input"
              @input="onSearchInput"
              @focus="onSearchFocus"
              @blur="onSearchBlur"
            />
            <div class="search-icon">
              <mobile-l-img src="/static/images/conversation/search_icon.png" w="20px" h="20px" />
            </div>
          </div>
        </div>
        
        <!-- 内容区域 -->
        <div class="dialog-content" ref="contentRef">
          <!-- History 标题 -->
          <div class="history-section">
            <h3 class="history-title">{{ t('history') }}</h3>
            
            <!-- 登录提示按钮 -->
            <div class="sign-in-prompt">
              <div @click="handleSignInClick" class="sign-in-button">
                {{ t('signInToSeeHistory') }}
              </div>
            </div>
          </div>
        </div>
        
        <!-- 底部安全区域 -->
        <div class="bottom-safe-area"></div>
      </div>
    </div>
  </BaseModal>
</template>

<script setup>
// 引入区域
import BaseModal from '@/components/dialog/open-dialog.vue';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import { ref, onMounted, onUnmounted } from 'vue';
import { t } from '@/language';

// props区域
const props = defineProps({
  zIndex: {
    type: Number,
    default: 3000
  },
  onClose: {
    type: Function,
    required: true
  },
  onSignIn: {
    type: Function,
    default: null
  },
  data: {
    type: Object,
    default: () => ({})
  }
});

// 变量区域
const contentRef = ref(null);
const searchQuery = ref('');

// 点击事件区域
const handleClose = () => {
  if (props.onClose) {
    props.onClose();
  }
};

const handleSignInClick = () => {
  const result = {
    action: 'signin',
    data: props.data
  };
  
  if (props.onSignIn) {
    props.onSignIn(result);
  } else {
    // 默认关闭弹窗
    handleClose();
  }
};

// 自定义事件区域
const onSearchInput = (event) => {
  searchQuery.value = event.target.value;
};

const onSearchFocus = () => {
  // 搜索框获得焦点
};

const onSearchBlur = () => {
  // 搜索框失去焦点
};
</script>

